<?php
declare(strict_types=1);
/** SOON.uz one-time production installer. */
if (file_exists(__DIR__ . '/includes/install.lock')) { http_response_code(403); exit("O'rnatish allaqachon yakunlangan."); }
if (version_compare(PHP_VERSION, '8.0.0', '<')) exit('PHP 8.0 yoki undan yuqori versiya talab qilinadi.');
foreach (['pdo','pdo_mysql','json','fileinfo'] as $ext) if (!extension_loaded($ext)) exit('Yetishmayotgan PHP kengaytmasi: '.$ext);
session_name('soon_installer'); session_set_cookie_params(['httponly'=>true,'secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'samesite'=>'Lax']); session_start();
if (empty($_SESSION['installer_csrf'])) $_SESSION['installer_csrf']=bin2hex(random_bytes(32));
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function p(string $k,string $d=''):string{return trim((string)($_POST[$k]??$d));}
function token():string{return '<input type="hidden" name="csrf_token" value="'.h($_SESSION['installer_csrf']).'">';}
function dbid(string $v):bool{return (bool)preg_match('/^[A-Za-z0-9_]{1,64}$/',$v);}
function pwErrors(string $v):array{$e=[];if(strlen($v)<12)$e[]='Parol kamida 12 belgidan iborat bo‘lsin.';if(!preg_match('/[A-Z]/',$v))$e[]='Katta harf kerak.';if(!preg_match('/[a-z]/',$v))$e[]='Kichik harf kerak.';if(!preg_match('/\d/',$v))$e[]='Raqam kerak.';if(!preg_match('/[^A-Za-z0-9]/',$v))$e[]='Maxsus belgi kerak.';return $e;}
function runSchema(PDO $pdo,string $file):void{
 $sql=file_get_contents($file);if($sql===false)throw new RuntimeException('Schema o‘qilmadi.');
 $sql=preg_replace('/^\s*CREATE DATABASE IF NOT EXISTS[^;]+;\s*/mi','',$sql);
 $sql=preg_replace('/^\s*USE\s+[^;]+;\s*/mi','',$sql);
 $sql=preg_replace('/-- Default Admin.*?ON DUPLICATE KEY UPDATE username=username;\s*/is','',$sql);
 $sql=preg_replace('/^\s*DELIMITER\s+\$\$\s*$/mi','',$sql);$sql=preg_replace('/^\s*DELIMITER\s+;\s*$/mi','',$sql);$sql=str_replace('$$',';',$sql);
 $statements=preg_split('/;\s*(?=(?:[^\'"`]*[\'"`][^\'"`]*[\'"`])*[^\'"`]*$)/',$sql);
 foreach($statements as $s){$s=trim($s);if($s===''||preg_match('/^(--|#)/',$s))continue;$pdo->exec($s);}
}
function writeConfig(array $c):void{
 $t=file_get_contents(__DIR__.'/includes/config.php.dist');if($t===false)throw new RuntimeException('config.php.dist topilmadi.');
 $t=strtr($t,['{{DB_HOST}}'=>$c['db_host'],'{{DB_NAME}}'=>$c['db_name'],'{{DB_USER}}'=>$c['db_user'],'{{DB_PASS}}'=>$c['db_pass'],'{{GOOGLE_CLIENT_ID}}'=>$c['google_client_id'],'{{GOOGLE_CLIENT_SECRET}}'=>$c['google_client_secret'],'{{GOOGLE_REDIRECT_URI}}'=>$c['google_redirect_uri'],'{{SITE_URL}}'=>rtrim($c['site_url'],'/')]);
 $q=['MAIL_HOST','MAIL_USERNAME','MAIL_PASSWORD','MAIL_ENCRYPTION','MAIL_FROM_ADDRESS','TELEGRAM_BOT_TOKEN','TELEGRAM_CHAT_ID','AI_GEMINI_KEY','AI_GROQ_KEY','AI_OPENROUTER_KEY'];
 $t.="\n// Optional integrations.\n";foreach($q as $k){$src=['MAIL_HOST'=>'mail_host','MAIL_USERNAME'=>'mail_username','MAIL_PASSWORD'=>'mail_password','MAIL_ENCRYPTION'=>'mail_encryption','MAIL_FROM_ADDRESS'=>'mail_from','TELEGRAM_BOT_TOKEN'=>'telegram_token','TELEGRAM_CHAT_ID'=>'telegram_chat_id','AI_GEMINI_KEY'=>'gemini_key','AI_GROQ_KEY'=>'groq_key','AI_OPENROUTER_KEY'=>'openrouter_key'][$k];$t.="define('$k', '".addslashes($c[$src]??'')."');\n";} $t.="define('MAIL_PORT', ".(int)($c['mail_port']??587). ");\n";
 if(file_put_contents(__DIR__.'/includes/config.php',$t,LOCK_EX)===false)throw new RuntimeException('config.php yozib bo‘lmadi.');@chmod(__DIR__.'/includes/config.php',0600);
}
function seedSettings(PDO $pdo,array $c):void{
 $rows=[['site_name',$c['site_name'],'string','general','Sayt nomi',1],['site_title',$c['site_name'].($c['tagline']?' — '.$c['tagline']:''),'string','seo','SEO title',1],['site_description',$c['about'],'text','seo','Meta description',1],['site_keywords','IT, web, dasturlash, raqamli xizmatlar, SOON','string','seo','SEO keywords',1],['site_url',rtrim($c['site_url'],'/'),'string','general','Canonical URL',1],['site_tagline',$c['tagline'],'string','general','Tagline',1],['founder_name',$c['founder'],'string','general','Founder',1],['contact_phone',$c['phone'],'string','contact','Telefon',1],['contact_email',$c['email'],'string','contact','Email',1],['contact_telegram',$c['telegram'],'string','contact','Telegram',1],['contact_instagram',$c['instagram'],'string','contact','Instagram',1],['contact_address',$c['address'],'string','contact','Manzil',1],['theme_color','#6366f1','string','design','Asosiy rang',1],['theme_accent_color','#06b6d4','string','design','Accent rang',1],['logo_path','','string','branding','Logo',1],['banner_path','','string','branding','Banner',1],['favicon_path','','string','branding','Favicon',1],['og_image_path','','string','branding','OG image',1],['registration_enabled','1','boolean','system','Registration',0],['maintenance_mode','0','boolean','system','Maintenance',0]];
 $s=$pdo->prepare('INSERT INTO settings (setting_key,setting_value,setting_type,group_name,description,is_public) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($rows as $r)$s->execute($r);
}
$step=max(1,min(4,(int)($_GET['step']??1)));$error='';$success=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['installer_csrf']??'',(string)($_POST['csrf_token']??''))){http_response_code(419);exit('CSRF xatosi.');}
 try{
  if($step===1){$url=rtrim(p('site_url'),'/' );if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('Sayt URL noto‘g‘ri.');$_SESSION['site']=['site_name'=>p('site_name','SOON'),'site_url'=>$url,'tagline'=>p('tagline'),'about'=>p('about'),'founder'=>p('founder'),'email'=>p('email'),'phone'=>p('phone'),'address'=>p('address'),'telegram'=>p('telegram'),'instagram'=>p('instagram')];header('Location: ?step=2');exit;}
  if($step===2){$db=['db_host'=>p('db_host','localhost'),'db_name'=>p('db_name','soon_uz'),'db_user'=>p('db_user'),'db_pass'=>$_POST['db_pass']??''];if(!dbid($db['db_name']))throw new RuntimeException('Database nomi noto‘g‘ri.');$pdo=new PDO('mysql:host='.$db['db_host'].';charset=utf8mb4',$db['db_user'],$db['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec('CREATE DATABASE IF NOT EXISTS `'.$db['db_name'].'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$_SESSION['db']=$db;header('Location: ?step=3');exit;}
  if($step===3){$u=p('admin_username');$n=p('admin_name');$e=p('admin_email');$pw=(string)($_POST['admin_password']??'');if(!preg_match('/^[A-Za-z0-9_.-]{3,50}$/',$u))throw new RuntimeException('Admin username noto‘g‘ri.');if(!filter_var($e,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Admin email noto‘g‘ri.');if($n==='')throw new RuntimeException('Admin ismini kiriting.');$pe=pwErrors($pw);if($pe)throw new RuntimeException(implode(' ',$pe));$_SESSION['admin']=['username'=>$u,'name'=>$n,'email'=>$e,'password_hash'=>password_hash($pw,PASSWORD_ARGON2ID)];header('Location: ?step=4');exit;}
  if($step===4){if(empty($_SESSION['site'],$_SESSION['db'],$_SESSION['admin']))throw new RuntimeException('Installer sessiyasi to‘liq emas.');$c=array_merge($_SESSION['site'],$_SESSION['db'],$_SESSION['admin'],['google_client_id'=>p('google_client_id'),'google_client_secret'=>p('google_client_secret'),'google_redirect_uri'=>p('google_redirect_uri'),'mail_host'=>p('mail_host'),'mail_port'=>p('mail_port','587'),'mail_username'=>p('mail_username'),'mail_password'=>(string)($_POST['mail_password']??''),'mail_encryption'=>p('mail_encryption','tls'),'mail_from'=>p('mail_from'),'telegram_token'=>(string)($_POST['telegram_token']??''),'telegram_chat_id'=>p('telegram_chat_id'),'gemini_key'=>(string)($_POST['gemini_key']??''),'groq_key'=>(string)($_POST['groq_key']??''),'openrouter_key'=>(string)($_POST['openrouter_key']??'')]);$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);runSchema($pdo,__DIR__.'/database/schema.sql');$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO admins (username,password_hash,full_name,email,role,status) VALUES (?,?,?,?,?,?)');$s->execute([$c['username'],$c['password_hash'],$c['name'],$c['email'],'super_admin','active']);seedSettings($pdo,$c);$pdo->commit();writeConfig($c);if(!is_dir(__DIR__.'/uploads'))@mkdir(__DIR__.'/uploads',0755,true);file_put_contents(__DIR__.'/includes/install.lock',date('c'),LOCK_EX);session_destroy();$success=true;}
 }catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$site=$_SESSION['site']??['site_name'=>'SOON','site_url'=>'https://soon.uz','tagline'=>'','about'=>'','founder'=>'','email'=>'','phone'=>'','address'=>'','telegram'=>'','instagram'=>''];
?><!doctype html><html lang="uz"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SOON — Installer</title><style>body{margin:0;font:15px system-ui;background:#f4f6f8;color:#111827}.wrap{max-width:760px;margin:40px auto;padding:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:24px;padding:28px;box-shadow:0 18px 50px #0000000b}h1{margin:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{margin-bottom:14px}.full{grid-column:1/-1}label{display:block;font-weight:650;margin-bottom:6px}input,textarea,select{width:100%;box-sizing:border-box;padding:12px;border:1px solid #d1d5db;border-radius:12px;font:inherit}textarea{min-height:90px}.steps{display:flex;gap:6px;margin:18px 0;flex-wrap:wrap}.steps b{padding:7px 10px;border-radius:999px;background:#eef2ff}.err{padding:12px;background:#fef2f2;color:#991b1b;border-radius:12px;margin-bottom:15px}.ok{padding:18px;background:#ecfdf5;color:#065f46;border-radius:16px}button{border:0;border-radius:12px;padding:13px 18px;background:#111827;color:#fff;font-weight:700}@media(max-width:650px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><div class="wrap"><div class="card"><h1>SOON</h1><p>Production Installer · bir martalik xavfsiz o‘rnatish</p><div class="steps"><b>1 Site</b><b>2 DB</b><b>3 Admin</b><b>4 Integratsiya</b></div><?php if($error):?><div class="err"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="ok"><strong>O‘rnatish muvaffaqiyatli yakunlandi.</strong><p>Admin panelga kirishingiz mumkin. install.lock yaratildi.</p></div><?php else:?><form method="post" autocomplete="off"><?=token()?><?php if($step===1):?><div class="grid"><div class="field"><label>Sayt nomi</label><input name="site_name" value="<?=h($site['site_name'])?>" required></div><div class="field"><label>Sayt URL</label><input name="site_url" type="url" value="<?=h($site['site_url'])?>" required></div><div class="field"><label>Tagline</label><input name="tagline"></div><div class="field"><label>Founder</label><input name="founder"></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Telefon</label><input name="phone"></div><div class="field"><label>Telegram</label><input name="telegram"></div><div class="field"><label>Instagram</label><input name="instagram"></div><div class="field full"><label>Manzil</label><input name="address"></div><div class="field full"><label>About</label><textarea name="about"></textarea></div></div><?php elseif($step===2):$db=$_SESSION['db']??['db_host'=>'localhost','db_name'=>'soon_uz','db_user'=>''];?><div class="grid"><div class="field"><label>MySQL host</label><input name="db_host" value="<?=h($db['db_host'])?>" required></div><div class="field"><label>Database name</label><input name="db_name" value="<?=h($db['db_name'])?>" required></div><div class="field"><label>MySQL user</label><input name="db_user" value="<?=h($db['db_user'])?>" required></div><div class="field"><label>MySQL password</label><input name="db_pass" type="password"></div></div><?php elseif($step===3):$a=$_SESSION['admin']??['username'=>'admin','name'=>'','email'=>''];?><div class="grid"><div class="field"><label>Username</label><input name="admin_username" value="<?=h($a['username'])?>" required></div><div class="field"><label>To‘liq ism</label><input name="admin_name" required></div><div class="field"><label>Email</label><input name="admin_email" type="email" required></div><div class="field"><label>Kuchli parol</label><input name="admin_password" type="password" required></div></div><p>Kamida 12 belgi: katta/kichik harf, raqam va maxsus belgi.</p><?php else:?><h3>Google OAuth (ixtiyoriy)</h3><div class="grid"><div class="field"><label>Client ID</label><input name="google_client_id"></div><div class="field"><label>Client Secret</label><input name="google_client_secret" type="password"></div><div class="field full"><label>Redirect URI</label><input name="google_redirect_uri"></div></div><h3>SMTP (ixtiyoriy)</h3><div class="grid"><div class="field"><label>Host</label><input name="mail_host"></div><div class="field"><label>Port</label><input name="mail_port" value="587"></div><div class="field"><label>Username</label><input name="mail_username"></div><div class="field"><label>Password</label><input name="mail_password" type="password"></div><div class="field"><label>Encryption</label><select name="mail_encryption"><option>tls</option><option>ssl</option></select></div><div class="field"><label>From email</label><input name="mail_from" type="email"></div></div><h3>Telegram / AI (ixtiyoriy)</h3><div class="grid"><div class="field"><label>Telegram Bot Token</label><input name="telegram_token" type="password"></div><div class="field"><label>Telegram Chat ID</label><input name="telegram_chat_id"></div><div class="field"><label>Gemini API Key</label><input name="gemini_key" type="password"></div><div class="field"><label>Groq API Key</label><input name="groq_key" type="password"></div><div class="field full"><label>OpenRouter API Key</label><input name="openrouter_key" type="password"></div></div><?php endif;?><button type="submit"><?=$step===4?'SOON’ni o‘rnatish':'Davom etish'?></button></form><?php endif;?></div></div></body></html>